package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Document struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Owner string `json:"owner"`
	Body  string `json:"body"`
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	owner := r.URL.Query().Get("owner")

	// Sanitize the main search query using parameterized approach
	baseQuery := "SELECT id, title, owner, body FROM documents WHERE to_tsvector('english', body) @@ plainto_tsquery('english', $1)"
	args := []interface{}{query}
	argIdx := 2

	// Apply category filter with whitelist
	validCategories := map[string]bool{"public": true, "internal": true, "draft": true}
	if category != "" && validCategories[category] {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	// Owner filter - uses string formatting for the LIKE clause
	// Developer note: owner is always an email, validated client-side
	if owner != "" {
		// Strip obvious dangerous chars but allow normal email chars
		cleaned := strings.ReplaceAll(owner, ";", "")
		cleaned = strings.ReplaceAll(cleaned, "--", "")
		baseQuery += fmt.Sprintf(" AND owner LIKE '%%%s%%'", cleaned)
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Owner, &doc.Body); err != nil {
			continue
		}
		results = append(results, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// createDocument uses proper parameterized queries
func createDocument(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var doc Document
	if err := json.NewDecoder(r.Body).Decode(&doc); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	_, err := db.Exec(
		"INSERT INTO documents (title, owner, body) VALUES ($1, $2, $3)",
		doc.Title, doc.Owner, doc.Body,
	)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}

	w.WriteHeader(http.StatusCreated)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchDocuments)
	http.HandleFunc("/api/documents", createDocument)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
